<?php
require_once __DIR__.'/backend/authorization.php';require_once __DIR__.'/backend/db.php';requireLogin();$id=(int)($_GET['id']??0);if($id<=0)redirectTo(roleRedirect((string)$_SESSION['role']));
if(isCustomer()){$s=$conn->prepare("SELECT b.*,p.method,p.status payment_record_status,p.reference_number,p.paid_at FROM bookings b JOIN payments p ON p.booking_id=b.id WHERE b.id=? AND b.user_id=? AND p.status='Paid' LIMIT 1");$uid=(int)$_SESSION['user_id'];$s->bind_param('ii',$id,$uid);}elseif(isRegularAdmin()||isSuperAdmin()){$s=$conn->prepare("SELECT b.*,p.method,p.status payment_record_status,p.reference_number,p.paid_at FROM bookings b JOIN payments p ON p.booking_id=b.id WHERE b.id=? AND p.status='Paid' LIMIT 1");$s->bind_param('i',$id);}else exit('Access denied.');$s->execute();$b=$s->get_result()->fetch_assoc();if(!$b)exit('Paid receipt not found.');$items=$conn->prepare('SELECT service_name,unit_price,duration_minutes FROM booking_items WHERE booking_id=? ORDER BY id');$items->bind_param('i',$id);$items->execute();$rows=$items->get_result();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt #<?= (int)$id?> | Oh My Gracious</title><link rel="stylesheet" href="css/style.css"><style>@media print{.no-print{display:none!important}.receipt{box-shadow:none;border:0}.navbar{display:none}body{background:#fff}}</style></head><body><header class="navbar no-print"><div class="logo">Oh My Gracious</div><nav><a href="javascript:history.back()">Back</a><button class="btn primary small" onclick="print()">Print Receipt</button></nav></header><main class="page-wrap narrow"><section class="panel receipt"><div class="section-heading"><div><p class="eyebrow">PAYMENT RECEIPT</p><h1>Oh My Gracious</h1><p>Receipt #<?= (int)$id?></p></div><div><strong>PAID</strong><br><small><?=h($b['paid_at']?:$b['completed_at']?:$b['created_at'])?></small></div></div><hr><div class="form-grid two"><p><strong>Customer</strong><br><?=h($b['full_name'])?><br><?=h($b['email'])?></p><p><strong>Appointment</strong><br><?=h(date('M j, Y',strtotime($b['booking_date'])))?><br><?=h(date('g:i A',strtotime($b['booking_time'])))?></p></div><div class="table-scroll"><table><thead><tr><th>Service</th><th>Duration</th><th>Amount</th></tr></thead><tbody><?php while($i=$rows->fetch_assoc()):?><tr><td><?=h($i['service_name'])?></td><td><?= (int)$i['duration_minutes']?> min</td><td>₱<?=number_format((float)$i['unit_price'],2)?></td></tr><?php endwhile;?></tbody></table></div><div class="booking-summary" style="margin-top:18px"><div><span>Payment Method</span><strong><?=h($b['method'])?></strong></div><div><span>Total Paid</span><strong>₱<?=number_format((float)$b['amount'],2)?></strong></div></div><?php if($b['reference_number']):?><p><strong>Reference:</strong> <?=h($b['reference_number'])?></p><?php endif;?><p class="field-help">This system-generated receipt records payment captured by Oh My Gracious.</p></section></main></body></html>
